INSERT INTO legends.figures (slug, name, born, died, country, known_for, bio) VALUES
('steve-jobs', 'Steve Jobs', 1955, 2011, 'United States', 'Apple, Macintosh, iPhone', 'Co-founded Apple, founded NeXT, led Pixar, returned to Apple and launched the iPod and iPhone.'),
('steve-wozniak', 'Steve Wozniak', 1950, NULL, 'United States', 'Apple I and Apple II', 'Engineer who designed the Apple I and Apple II personal computers.'),
('bill-gates', 'Bill Gates', 1955, NULL, 'United States', 'Microsoft, MS-DOS, Windows', 'Co-founded Microsoft and led it through MS-DOS and Windows.'),
('ada-lovelace', 'Ada Lovelace', 1815, 1852, 'United Kingdom', 'First published algorithm', 'Wrote notes on Babbage''s Analytical Engine that include an algorithm for a machine.'),
('alan-turing', 'Alan Turing', 1912, 1954, 'United Kingdom', 'Turing machine, codebreaking', 'Formalised computation with the Turing machine and worked on wartime codebreaking.'),
('grace-hopper', 'Grace Hopper', 1906, 1992, 'United States', 'Compilers, COBOL', 'Built one of the first compilers and pushed for English-like programming languages.'),
('linus-torvalds', 'Linus Torvalds', 1969, NULL, 'Finland', 'Linux, Git', 'Started the Linux kernel as a student and later wrote Git.'),
('tim-berners-lee', 'Tim Berners-Lee', 1955, NULL, 'United Kingdom', 'World Wide Web', 'Invented the World Wide Web at CERN and founded the W3C.'),
('margaret-hamilton', 'Margaret Hamilton', 1936, NULL, 'United States', 'Apollo flight software', 'Led the team that wrote the on-board flight software for the Apollo missions.'),
('dennis-ritchie', 'Dennis Ritchie', 1941, 2011, 'United States', 'C language, Unix', 'Created the C programming language and co-created Unix at Bell Labs.'),
('jensen-huang', 'Jensen Huang', 1963, NULL, 'United States', 'NVIDIA, GPUs, CUDA', 'Co-founded NVIDIA and led it from graphics chips to GPU computing.'),
('fei-fei-li', 'Fei-Fei Li', 1976, NULL, 'United States', 'ImageNet, computer vision', 'Created the ImageNet dataset that helped start the deep learning era in vision.');
